import{_ as a,c as e,o as s,b0 as d}from"./chunks/framework.Dmsv_Tiv.js";const n="/media-docs/assets/01-pipeline.ClSzRQWi.png",r="/media-docs/assets/02-bayer-raw10.CEtoMtDM.png",o="/media-docs/assets/03-demosaic.BBipor1N.png",i="/media-docs/assets/04-yuv420-downsample.CqnDPP9y.png",p="/media-docs/assets/05-file-layout.DpmvDk3W.png",l="/media-docs/assets/06-size-compare.BLm7InEv.png",P=JSON.parse('{"title":"LV025-从Bayer到YUV420的流程","description":null,"frontmatter":{"title":"LV025-从Bayer到YUV420的流程","date":"2026-10-11T21:27:07.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/color-model/126d626049a32fac7f63d30c","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-11T21:27:07.762Z","fulluuid":"c7f63d30c9014ebcb968acd718e742f0","useduuid":"c7f63d30c"}},"headers":[],"relativePath":"sdoc/image/color-model/126d626049a32fac7f63d30c.md","filePath":"sdoc/01-图像/20-常用色彩模型/LV025-从Bayer到YUV420的流程.md","lastUpdated":1791732734000}'),c={name:"sdoc/image/color-model/126d626049a32fac7f63d30c.md"};function b(h,t,u,m,R,B){return s(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="lv025-从bayer到yuv420的流程" tabindex="-1">LV025-从Bayer到YUV420的流程 <a class="header-anchor" href="#lv025-从bayer到yuv420的流程" aria-label="Permalink to &quot;LV025-从Bayer到YUV420的流程&quot;">​</a></h1><h2 id="一、-链路总览" tabindex="-1">一、 链路总览 <a class="header-anchor" href="#一、-链路总览" aria-label="Permalink to &quot;一、 链路总览&quot;">​</a></h2><p>相机从“看到光”到“存成一个文件”，中间要经过传感器采样、ISP 处理、色彩空间转换、色度下采样，最后才落盘。以 1920x1080、10bit Bayer 为例，整条链路是这样的：</p><p><img src="'+n+`" alt="01-pipeline"></p><table tabindex="0"><thead><tr><th>阶段</th><th>数据形态</th><th>位宽</th><th>每像素占用</th><th>1920x1080 一帧</th></tr></thead><tbody><tr><td>传感器输出</td><td>Bayer RAW，每像素 1 个分量</td><td>10bit（RAW10 打包）</td><td>1.25 字节</td><td>2.47 MB</td></tr><tr><td>ISP 内部</td><td>仍是 Bayer，每像素 1 个分量</td><td>10 ~ 12bit</td><td>2 字节（解包后按 16bit 放）</td><td>3.96 MB</td></tr><tr><td>去马赛克之后</td><td>每像素 R、G、B</td><td>8bit x 3</td><td>3 字节</td><td>5.93 MB</td></tr><tr><td>RGB → YUV</td><td>YUV444</td><td>8bit x 3</td><td>3 字节</td><td>5.93 MB</td></tr><tr><td>色度下采样 4:2:0</td><td>YUV420</td><td>8bit(Y) + 8bit(U/V)/4</td><td>1.5 字节</td><td>2.97 MB</td></tr><tr><td>存储到文件</td><td>I420 / NV12 裸数据</td><td>8bit</td><td>1.5 字节</td><td>2.97 MB</td></tr></tbody></table><p>（表里的 MB 按 1024 进制换算，下同。）</p><p>这里有个反直觉的结论，先放出来：<strong>处理完的 YUV420（2.97MB）比传感器原始输出的 Bayer RAW（2.47MB）还大</strong>。为什么越大越处理、越处理越大，看完下面几步就明白了。</p><h2 id="二、-从-sensor-到-yuv420-的处理流程" tabindex="-1">二、 从 sensor 到 YUV420 的处理流程 <a class="header-anchor" href="#二、-从-sensor-到-yuv420-的处理流程" aria-label="Permalink to &quot;二、 从 sensor 到 YUV420 的处理流程&quot;">​</a></h2><h3 id="_1-采集-怎么从-sensor-拿到-bayer-数据" tabindex="-1">1. 采集：怎么从 sensor 拿到 Bayer 数据 <a class="header-anchor" href="#_1-采集-怎么从-sensor-拿到-bayer-数据" aria-label="Permalink to &quot;1. 采集：怎么从 sensor 拿到 Bayer 数据&quot;">​</a></h3><p>前面那张表是从“传感器输出”开始算的。但数据不会凭空出现在 SoC 里——从配置 sensor 到 ISP 拿到 Bayer，中间还有一段采集通路：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sensor：光电转换 → 模拟增益 → ADC → 数字 RAW（Bayer）</span></span>
<span class="line"><span>   ↓ DVP 并口 或 MIPI CSI-2（差分，经 D-PHY）</span></span>
<span class="line"><span>SoC 侧：D-PHY → CSI2RX 控制器（或 VICAP）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>ISP 流水线（或先落到 DDR）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="_1-1-先把-sensor-配起来" tabindex="-1">1.1 先把 sensor 配起来 <a class="header-anchor" href="#_1-1-先把-sensor-配起来" aria-label="Permalink to &quot;1.1 先把 sensor 配起来&quot;">​</a></h4><p>sensor 上电不会自己出图，主控要先通过 <strong>I2C</strong> 配置它的寄存器：分辨率、像素格式（RAW8/RAW10/RAW12）、帧率、曝光、增益，并读 OTP 里的模组标定数据。在 MIPI 体系里这条控制总线叫 <strong>CCI（Camera Control Interface）</strong>，本质仍是 I2C，见《<a href="/media-docs/sdoc/mipi/csi/126b1449f33e15374f49df40.html">LV010-CCI</a>》。</p><p>除总线外还得给足：外部时钟（MCLK，常见 24MHz，sensor 内部 PLL 再倍频出像素时钟）、电源时序（AVDD/DOVDD/DVDD）、reset/powerdown 控制。</p><h4 id="_1-2-sensor-内部怎么-产生-bayer" tabindex="-1">1.2 sensor 内部怎么“产生” Bayer <a class="header-anchor" href="#_1-2-sensor-内部怎么-产生-bayer" aria-label="Permalink to &quot;1.2 sensor 内部怎么“产生” Bayer&quot;">​</a></h4><p>光打进感光区转成电荷，经模拟增益、逐行 ADC 变成数字值。每个像素前盖着 R/Gr/Gb/B 之一，所以读出来每像素只有 1 个分量；ADC 的位深决定 RAW 位宽（10bit 最常用）。输出的行、帧节奏由同步信号控制。</p><h4 id="_1-3-数据怎么传出来-dvp-还是-mipi" tabindex="-1">1.3 数据怎么传出来：DVP 还是 MIPI <a class="header-anchor" href="#_1-3-数据怎么传出来-dvp-还是-mipi" aria-label="Permalink to &quot;1.3 数据怎么传出来：DVP 还是 MIPI&quot;">​</a></h4><ul><li><strong>MIPI CSI-2 + D-PHY（主流）</strong>：数据走差分对，一般是 1 组时钟 + 1/2/4 组数据 lane。<strong>CSI-2 是协议层</strong>（打包、帧/行起始、虚拟通道、多路复用），<strong>D-PHY 是物理层</strong>（差分电气）。RAW10 之类的打包就发生在这一层，接口细节见《<a href="/media-docs/sdoc/mipi/mipi-intro/126b140b63d636e6bb6435d6.html">LV005-MIPI简介</a>》和《<a href="/media-docs/sdoc/mipi/dphy/126b143a8b643417e9e21932.html">LV005-MIPI-Sensor接口原理图</a>》。</li><li><strong>DVP 并口（老式、低分辨率）</strong>：PCLK + HSYNC + VSYNC + 8/10/12 位并行数据线，协议为 ITU-R BT.601/656、BT.1120。</li></ul><h4 id="_1-4-soc-侧怎么接住-以-rk3568-为例" tabindex="-1">1.4 SoC 侧怎么接住（以 RK3568 为例） <a class="header-anchor" href="#_1-4-soc-侧怎么接住-以-rk3568-为例" aria-label="Permalink to &quot;1.4 SoC 侧怎么接住（以 RK3568 为例）&quot;">​</a></h4><p>进入 SoC 后通常分两级：<strong>D-PHY</strong> 先把差分信号还原成字节流（PPI），再由 <strong>CSI2RX 控制器</strong>解析 CSI-2 包、还原成像素交给 ISP；CSI2RX 还支持 HDR 多帧、PDAF，并内置 <strong>FPN</strong>（固定模式噪声）去除。</p><p>到这里数据有两条去向：</p><ul><li><strong>处理通路</strong>：进 ISP 流水线（ISP 自带 CSI2RX，可直接对接 PHY 器件）。</li><li><strong>直存通路</strong>：进 <strong>VICAP（Video Capture）</strong>，由它把 DVP / MIPI(CSI2) 数据经 DMA、AXI 直接写进 DDR，不经过 ISP 处理。</li></ul><p>ISP 的输入能力：DVP 支持 BT.601/656（RAW8/10/12、YUV422）与 BT.1120；MIPI 支持 1/2/4 lane、RAW8/10/12、YUV422；最大输入 4096x2304。</p><p>—— 《<a href="https://cnb.cool/smk.k/LubanCat/dev-docs/-/blob/main/RockChip%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3/Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf" target="_blank" rel="noreferrer">Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf</a>》12.1 Overview（P.981）、12.3.1 CSI2RX（P.982–983）、Chapter 11 VICAP（P.948）</p><h3 id="_2-传感器吐出来的-bayer-raw-10bit" tabindex="-1">2. 传感器吐出来的 Bayer RAW（10bit） <a class="header-anchor" href="#_2-传感器吐出来的-bayer-raw-10bit" aria-label="Permalink to &quot;2. 传感器吐出来的 Bayer RAW（10bit）&quot;">​</a></h3><h4 id="_2-1-bayer-阵列-每个像素只有一个分量" tabindex="-1">2.1 Bayer 阵列：每个像素只有一个分量 <a class="header-anchor" href="#_2-1-bayer-阵列-每个像素只有一个分量" aria-label="Permalink to &quot;2.1 Bayer 阵列：每个像素只有一个分量&quot;">​</a></h4><p><img src="`+r+`" alt="02-bayer-raw10"></p><p>传感器上每个感光点前面都盖着一片滤色片，只让红、绿、蓝中的一种光通过，所以<strong>一个像素只有一个分量</strong>。最常见的排布是 RGGB（第一行 R、Gr，第二行 Gb、B），此外还有 BGGR、GRBG、GBRG 三种，统称 Bayer 阵列（CFA）。</p><p>图中绿色写成了 Gr、Gb，而不是笼统的一个 G，这里说明一下：<strong>与 R 同一行的绿叫 Gr，与 B 同一行的绿叫 Gb</strong>。分开标是有原因的：</p><ul><li><strong>一是相位</strong>：只有区分开才能准确描述四种排布，RGGB 是 <code>R Gr / Gb B</code>，BGGR 是 <code>B Gb / Gr R</code>，GRBG 是 <code>Gr R / B Gb</code>，GBRG 是 <code>Gb B / R Gr</code>；否则单说一个“绿”，根本讲不清它挨着的是 R 还是 B。</li><li><strong>二是 Gr、Gb 在 ISP 里就是两条通道</strong>：相邻滤色片的串扰、微透镜的角度响应，会让两者对同一束光的响应略有差异，所以白平衡常常按 R/Gr/Gb/B 四通道各给一个增益，去马赛克时两者的插值路径也不同。</li></ul><p>只写一个 G 不算错（不少资料为了简洁就是这么画的），但会丢掉这两层信息。</p><p>绿色占了一半的感光点，是因为人眼对绿色最敏感，而绿色也携带了最多的亮度信息。</p><p>Bayer 长什么样、插值算法怎么写，在《<a href="/media-docs/sdoc/image/img-basic/126b088c78041a6882f826f9.html">LV010-bayer格式</a>》里已经讲过，这里不重复，只关注数据怎么流动。</p><h4 id="_2-2-10bit-是怎么装进字节里的" tabindex="-1">2.2 10bit 是怎么装进字节里的 <a class="header-anchor" href="#_2-2-10bit-是怎么装进字节里的" aria-label="Permalink to &quot;2.2 10bit 是怎么装进字节里的&quot;">​</a></h4><p>10bit 不是整数个字节，所以要么按 16bit（2 字节）对齐存放，要么打包。相机和 SoC 之间走 MIPI CSI-2（见《<a href="/media-docs/sdoc/mipi/mipi-intro/126b140b63d636e6bb6435d6.html">LV005-MIPI简介</a>》），用的就是打包格式：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RAW10：4 个像素 -&gt; 5 个字节</span></span>
<span class="line"><span>       Byte0 ~ Byte3 = P0 ~ P3 的高 8 位</span></span>
<span class="line"><span>       Byte4         = P0、P1、P2、P3 各自剩下的低 2 位（4 x 2 = 8 位，刚好凑一个字节）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>也就是图上画的那样：4 x 10bit = 40bit = 5Byte，平均 10bit/像素 = 1.25 字节/像素。</p><table tabindex="0"><thead><tr><th>RAW 格式</th><th>每像素位宽</th><th>打包方式</th><th>每像素占用</th><th>1920x1080 一帧</th></tr></thead><tbody><tr><td>RAW8</td><td>8bit</td><td>1 像素 1 字节</td><td>1 字节</td><td>1.98 MB</td></tr><tr><td>RAW10</td><td>10bit</td><td>4 像素 5 字节</td><td>1.25 字节</td><td>2.47 MB</td></tr><tr><td>RAW12</td><td>12bit</td><td>2 像素 3 字节</td><td>1.5 字节</td><td>2.97 MB</td></tr><tr><td>RAW14</td><td>14bit</td><td>4 像素 7 字节</td><td>1.75 字节</td><td>3.46 MB</td></tr><tr><td>RAW16</td><td>16bit</td><td>1 像素 2 字节</td><td>2 字节</td><td>3.96 MB</td></tr></tbody></table><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RAW10，1920x1080：</span></span>
<span class="line"><span>2073600 x 10 / 8 = 2592000 Byte = 2531.25 KB ≈ 2.47 MB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>注意“打包”只存在于传输和存储环节：ISP 拿到数据后一般会先解包成 16bit 对齐再来算，所以同一个 sensor，RAW10 传出来 2.47MB，到了 ISP 内部就变成 3.96MB 了。</p><h3 id="_3-isp-把-bayer-变成-rgb" tabindex="-1">3. ISP 把 Bayer 变成 RGB <a class="header-anchor" href="#_3-isp-把-bayer-变成-rgb" aria-label="Permalink to &quot;3. ISP 把 Bayer 变成 RGB&quot;">​</a></h3><h4 id="_3-1-处理链上每一步在做什么" tabindex="-1">3.1 处理链上每一步在做什么 <a class="header-anchor" href="#_3-1-处理链上每一步在做什么" aria-label="Permalink to &quot;3.1 处理链上每一步在做什么&quot;">​</a></h4><p>数据从 sensor 出来之后，进的是 ISP（Image Signal Processor）。不同厂商的流程不完全一样，但大体都包含这些步骤：</p><table tabindex="0"><thead><tr><th>步骤</th><th>干什么</th><th>位宽变化</th></tr></thead><tbody><tr><td>黑电平校正 BLC</td><td>减掉暗电流造成的底噪</td><td>10 ~ 12bit</td></tr><tr><td>镜头阴影校正 LSC</td><td>把镜头边缘偏暗的部分提亮</td><td>10 ~ 12bit</td></tr><tr><td>坏点校正 DPC</td><td>干掉个别坏掉的感光点</td><td>10 ~ 12bit</td></tr><tr><td>去噪 NR</td><td>抑制暗光下的噪声</td><td>10 ~ 12bit</td></tr><tr><td>白平衡 AWB</td><td>R、G、B 各乘一个增益，让黑白灰不偏色</td><td>10 ~ 12bit</td></tr><tr><td><strong>去马赛克 Demosaic</strong></td><td><strong>插值补齐每个像素缺失的两个分量</strong></td><td><strong>每像素变成 3 个分量</strong></td></tr><tr><td>色彩校正 CCM</td><td>3x3 矩阵，把 sensor 的 RGB 拉到目标色域（如 sRGB）</td><td>8 ~ 12bit</td></tr><tr><td>Gamma / 色调曲线</td><td>把线性响应映射成符合人眼感知的曲线</td><td>8 ~ 12bit</td></tr><tr><td>色彩空间转换 CSC</td><td>RGB → YUV</td><td>8bit x 3</td></tr><tr><td>色度下采样</td><td>YUV444 → YUV420</td><td>8bit x 1.5</td></tr></tbody></table><p>至于为什么 ISP 内部要用比 sensor 更高的位深（比如 sensor 出 10bit、ISP 内部算 12bit），是为了在乘增益、做矩阵这些运算里少丢精度，最后再压到 8bit 输出。</p><p>这些步骤具体落在哪个硬件模块上，统一放在第三节讲。</p><h4 id="_3-2-去马赛克-1-个分量插成-3-个" tabindex="-1">3.2 去马赛克：1 个分量插成 3 个 <a class="header-anchor" href="#_3-2-去马赛克-1-个分量插成-3-个" aria-label="Permalink to &quot;3.2 去马赛克：1 个分量插成 3 个&quot;">​</a></h4><p><img src="`+o+`" alt="03-demosaic"></p><p>前面说 Bayer 每个像素只有 1 个分量，但屏幕上的一个像素需要 R、G、B 三个分量。去马赛克就是根据周围像素的颜色值，把每 2x2 里缺失的分量插值补出来。</p><p>这是整条链路上<strong>唯一让数据量变大的一步</strong>：每像素从 1 个分量变成 3 个分量，字节数直接翻 3 倍。而且要清楚一点——插值出来的像素里，只有 1/3 是真实采到的值，剩下的都是算出来的，真实信息量始终只有原始 RAW 那么多。</p><h3 id="_4-rgb-→-yuv" tabindex="-1">4. RGB → YUV <a class="header-anchor" href="#_4-rgb-→-yuv" aria-label="Permalink to &quot;4. RGB → YUV&quot;">​</a></h3><h4 id="_4-1-为什么要转" tabindex="-1">4.1 为什么要转 <a class="header-anchor" href="#_4-1-为什么要转" aria-label="Permalink to &quot;4.1 为什么要转&quot;">​</a></h4><p>因为接下来要“对色度下采样”，而<strong>前提是把亮度（Y）和色度（U/V）拆开</strong>。人眼对亮度敏感、对色度不敏感，只有拆开之后，才能单独把色度砍掉一半甚至四分之三而肉眼看不出区别。关于人眼特性和采样模式，见《<a href="/media-docs/sdoc/image/color-model/126b08d768c80d2ccc082ecc.html">LV020-YUV的格式</a>》。</p><h4 id="_4-2-转换公式" tabindex="-1">4.2 转换公式 <a class="header-anchor" href="#_4-2-转换公式" aria-label="Permalink to &quot;4.2 转换公式&quot;">​</a></h4><p>以 8bit 全范围（JPEG / PC 常用）为例，BT.601：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y  =  0.299R + 0.587G + 0.114B</span></span>
<span class="line"><span>Cb = -0.169R - 0.331G + 0.500B + 128</span></span>
<span class="line"><span>Cr =  0.500R - 0.419G - 0.081B + 128</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>BT.709（HD 常用）：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y  =  0.2126R + 0.7152G + 0.0722B</span></span>
<span class="line"><span>Cb = -0.1146R - 0.3854G + 0.5000B + 128</span></span>
<span class="line"><span>Cr =  0.5000R - 0.4542G - 0.0458B + 128</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>系数不同、还有 16~235 的“电视范围”和 0~255 的“全范围”之分，细节见《<a href="/media-docs/sdoc/image/color-model/126b08d6e2d2123655ee0da0.html">LV015-YUV与RGB转换</a>》。</p><h4 id="_4-3-此时还是-yuv444" tabindex="-1">4.3 此时还是 YUV444 <a class="header-anchor" href="#_4-3-此时还是-yuv444" aria-label="Permalink to &quot;4.3 此时还是 YUV444&quot;">​</a></h4><p>转完还是每个像素一个 Y + 一个 U + 一个 V，也就是 YUV444，<strong>每像素 3 字节，和 RGB 一样大</strong>。到这一步只是换了坐标系，一点空间都没省。</p><h3 id="_5-色度下采样成-4-2-0" tabindex="-1">5. 色度下采样成 4:2:0 <a class="header-anchor" href="#_5-色度下采样成-4-2-0" aria-label="Permalink to &quot;5. 色度下采样成 4:2:0&quot;">​</a></h3><p><img src="`+i+`" alt="04-yuv420-downsample"></p><p>4:2:0 的含义、以及为什么是“2x2 的 4 个像素共用一组 UV”，在《<a href="/media-docs/sdoc/image/color-model/126b08d768c80d2ccc082ecc.html">LV020-YUV的格式</a>》里详细讲过，这里一句话带过：U、V 在水平和垂直方向上都按 2:1 采样，亮度保持全采样。</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单个像素占用 = 1Byte(Y) + 1Byte(U)/4 + 1Byte(V)/4 = 1.5Byte</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1920x1080 一帧：</span></span>
<span class="line"><span>2073600 x 1.5 = 3110400 Byte = 3037.5 KB ≈ 2.97 MB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>到这一步，“3 字节/像素”变成了“1.5 字节/像素”，相比 RGB888 正好省一半，这也是 YUV420 成为相机、视频、播放器默认格式的原因。</p><h3 id="_6-写进文件是什么样" tabindex="-1">6. 写进文件是什么样 <a class="header-anchor" href="#_6-写进文件是什么样" aria-label="Permalink to &quot;6. 写进文件是什么样&quot;">​</a></h3><h4 id="_6-1-yuv-文件里没有头信息" tabindex="-1">6.1 YUV 文件里没有头信息 <a class="header-anchor" href="#_6-1-yuv-文件里没有头信息" aria-label="Permalink to &quot;6.1 YUV 文件里没有头信息&quot;">​</a></h4><p>和 BMP、JPEG 不一样，<strong>YUV 文件没有任何头和元数据</strong>：没有宽高、没有采样格式、没有位深，只有一大坨裸像素。所以拿到一个 <code>.yuv</code> 文件，必须外部约定好“1920x1080 + I420”这样的信息才能正确显示（比如用 7yuv 打开时要手选格式）。</p><p>芯片之间传递时不是这样：buffer 一般自带描述信息（宽、高、stride、格式），落成“纯裸数据文件”之后这些就丢了。</p><h4 id="_6-2-i420-nv12-nv21-的排布" tabindex="-1">6.2 I420 / NV12 / NV21 的排布 <a class="header-anchor" href="#_6-2-i420-nv12-nv21-的排布" aria-label="Permalink to &quot;6.2 I420 / NV12 / NV21 的排布&quot;">​</a></h4><p><img src="`+p+`" alt="05-file-layout"></p><p>以 8x8 的图为例（Y 平面 8x8，U、V 平面各 4x4）：</p><table tabindex="0"><thead><tr><th>格式</th><th>排布</th><th>8x8 图的字节数</th><th>1920x1080 的字节数</th></tr></thead><tbody><tr><td>I420（YUV420P）</td><td>Y → U → V 三段分开</td><td>64 + 16 + 16 = 96</td><td>3110400</td></tr><tr><td>YV12</td><td>Y → V → U 三段分开</td><td>64 + 16 + 16 = 96</td><td>3110400</td></tr><tr><td>NV12（YUV420SP）</td><td>Y 一段，UV 交织一段（UVUV…）</td><td>64 + 32 = 96</td><td>3110400</td></tr><tr><td>NV21</td><td>Y 一段，VU 交织一段（VUVU…）</td><td>64 + 32 = 96</td><td>3110400</td></tr></tbody></table><p>1920x1080 的拆解：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y 平面：1920 x 1080 = 2073600 Byte</span></span>
<span class="line"><span>U 平面：960 x 540   = 518400  Byte</span></span>
<span class="line"><span>V 平面：960 x 540   = 518400  Byte</span></span>
<span class="line"><span>合计  ：3110400 Byte = 3037.5 KB ≈ 2.97 MB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>补充一点：硬件里为了内存对齐，Y 的行宽（stride）常会补齐到 16 / 32 / 64 的整数倍，此时 buffer（以及按 buffer 直接 dump 出来的文件）会比上面的理论值大一些。</p><h4 id="_6-3-一帧到底多大" tabindex="-1">6.3 一帧到底多大 <a class="header-anchor" href="#_6-3-一帧到底多大" aria-label="Permalink to &quot;6.3 一帧到底多大&quot;">​</a></h4><p><img src="`+l+`" alt="06-size-compare"></p><table tabindex="0"><thead><tr><th>格式</th><th>每像素占用</th><th>1920x1080 一帧</th></tr></thead><tbody><tr><td>Bayer RAW10（打包）</td><td>1.25 字节</td><td>2.47 MB</td></tr><tr><td>Bayer RAW（解包后按 16bit）</td><td>2 字节</td><td>3.96 MB</td></tr><tr><td>YUV420（8bit）</td><td>1.5 字节</td><td>2.97 MB</td></tr><tr><td>YUV422（8bit）</td><td>2 字节</td><td>3.96 MB</td></tr><tr><td>RGB888 / YUV444（8bit）</td><td>3 字节</td><td>5.93 MB</td></tr><tr><td>YUV420（10bit，P010）</td><td>2 字节</td><td>5.93 MB</td></tr></tbody></table><p>（P010 是把 10bit 的数放进 16bit 容器里存，所以又把体积拉回去了）</p><p>两个结论：</p><p>（1）<strong>YUV420（8bit）比 10bit 打包的 Bayer RAW 还大</strong>。色度下采样省下的是相对 RGB / YUV444 的体积，不是相对 RAW 的体积——RAW 才是这条链路上最“瘦”的形态，因为每个像素只有一个分量。</p><p>（2）到这一步为止都还是“一帧 2.97MB”的量级，真正把体积压下去的是后面的视频编码（H.264 / H.265 等），那属于视频编解码章节的内容。</p><h2 id="三、-各步骤对应的-isp-硬件模块" tabindex="-1">三、 各步骤对应的 ISP 硬件模块 <a class="header-anchor" href="#三、-各步骤对应的-isp-硬件模块" aria-label="Permalink to &quot;三、 各步骤对应的 ISP 硬件模块&quot;">​</a></h2><p>前面几节讲的是“做了什么”，这一节补上“由谁来做”。以 RK3568 的 ISP 为例，按 TRM 的划分，ISP 内部依次分四段：<strong>RAW Processing → RGB Processing → YUV Processing → Memory Interface（MI）</strong>（《<a href="https://cnb.cool/smk.k/LubanCat/dev-docs/-/blob/main/RockChip%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3/Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf" target="_blank" rel="noreferrer">Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf</a>》P.982）。</p><h3 id="_1-链路步骤-→-isp-模块对照" tabindex="-1">1. 链路步骤 → ISP 模块对照 <a class="header-anchor" href="#_1-链路步骤-→-isp-模块对照" aria-label="Permalink to &quot;1. 链路步骤 → ISP 模块对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>通用步骤</th><th>RK3568 模块</th><th>说明</th></tr></thead><tbody><tr><td>黑电平校正 BLC</td><td><code>BLS</code>（Black-level-subtraction）</td><td>从像素里减掉一个 DC 偏置；自动模式读传感器遮蔽像素求均值</td></tr><tr><td>镜头阴影校正 LSC</td><td><code>LSC</code></td><td>每个像素乘各自的校正系数，系数在 sector 角点之间做双线性插值</td></tr><tr><td>坏点校正 DPC</td><td><code>DPCC</code></td><td>静态 + 动态坏点/坏点簇校正，最大 3x3，静态表可存 2048 个位置</td></tr><tr><td>绿平衡</td><td><code>GIC</code></td><td>Green Imbalance Correction，修正绿通道不平衡</td></tr><tr><td>去噪 NR</td><td>RAW 域 <code>BAYNR</code>（空域）/ <code>BAY3D</code>（时域）；YUV 域 <code>2DNR</code>（<code>YNR</code> + <code>CNR</code>）</td><td>RAW 域分空域、时域两套，YUV 域再分亮度、色度</td></tr><tr><td>白平衡 AWB</td><td><code>RAWAWB</code>（统计）+ <code>AWB_GAIN</code>（增益）</td><td>统计在 RAW 域产生，增益按 R/Gr/Gb/B 四通道乘回</td></tr><tr><td>去马赛克 Demosaic</td><td><code>DEBAYER</code></td><td>插值 + 滤波输出 RGB；黑白模式下三通道输出同值</td></tr><tr><td>色彩校正 CCM</td><td><code>CCM</code></td><td>3x3 颜色校正矩阵</td></tr><tr><td>Gamma</td><td>RAW 域 <code>GAMMA_IN</code>、RGB 域 <code>GAMMA_OUT</code></td><td>输入侧贴合 sensor 特性，输出侧贴合人眼感知</td></tr><tr><td>色彩空间转换 RGB→YUV</td><td><code>CSM</code></td><td>Color Space Matrix</td></tr><tr><td>色度下采样到 4:2:0</td><td><code>CONV422</code> + <code>SELF_RESIZE</code> / <code>SCL</code></td><td>先做 444→422，再由 Resize 完成 422→420</td></tr></tbody></table><p>表内模块的功能见《<a href="https://cnb.cool/smk.k/LubanCat/dev-docs/-/blob/main/RockChip%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3/Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf" target="_blank" rel="noreferrer">Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf</a>》P.986–989，模块基地址见同文档 P.991 的 Table 12-2。</p><h3 id="_2-isp-内部按域分组" tabindex="-1">2. ISP 内部按域分组 <a class="header-anchor" href="#_2-isp-内部按域分组" aria-label="Permalink to &quot;2. ISP 内部按域分组&quot;">​</a></h3><p>【<strong>RAW Processing（RAW / Bayer 域）</strong>】</p><ul><li><code>FPN</code>：固定模式噪声去除，实现在 <code>CSI2RX(MIPI)</code> 里</li><li><code>BLS</code>、<code>DPCC</code>、<code>GAMMA_IN</code>、<code>LSC</code>、<code>GIC</code></li><li><code>HDRMGE</code>（多帧合成）、<code>HDRTMO</code>（DRC 宽动态压缩）</li><li><code>BAYNR</code>（空域降噪）、<code>BAY3D</code>（时域降噪）</li><li><code>AWB_GAIN</code>，以及 3A 统计模块 <code>RAWAWB</code>、<code>RAWAE_BIG</code> / <code>RAWAE_LITE</code>、<code>RAWAF</code>、<code>RAWHIST_BIG</code> / <code>RAWHIST_LITE</code>、<code>PDAF</code></li></ul><p>【<strong>RGB Processing</strong>】</p><ul><li><code>DEBAYER</code>、<code>CCM</code>、<code>GAMMA_OUT</code>、<code>DEHAZE_ENHANCE</code>、<code>3DLUT</code>、<code>LDCH</code></li></ul><p>【<strong>YUV Processing</strong>】</p><ul><li><code>2DNR</code>（<code>YNR</code> + <code>CNR</code>）、<code>SHARP</code>、<code>CSM</code>、<code>CONV422</code>、<code>SCL</code> / <code>SELF_RESIZE</code></li></ul><p>【<strong>Memory Interface（MI）</strong>】</p><ul><li>负责主路图像、MIPI、DBR、LUT 各通道与 DDR 之间的读写</li></ul><p>—— 《<a href="https://cnb.cool/smk.k/LubanCat/dev-docs/-/blob/main/RockChip%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3/Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf" target="_blank" rel="noreferrer">Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf</a>》P.982–991</p><h3 id="_3-三个容易忽略的点" tabindex="-1">3. 三个容易忽略的点 <a class="header-anchor" href="#_3-三个容易忽略的点" aria-label="Permalink to &quot;3. 三个容易忽略的点&quot;">​</a></h3><p>（1）<strong>3A 的统计在 RAW 域完成</strong>：<code>RAWAWB</code>、<code>RAWAE_*</code>、<code>RAWHIST_*</code> 吃的都是 raw 数据，硬件只负责“测量”，软件拿到统计量后算出增益、曝光、白平衡参数，再回填给 <code>AWB_GAIN</code> 等模块去“应用”。</p><p>（2）<strong>Gamma 有两个</strong>：RAW 域一个 <code>GAMMA_IN</code>，RGB 域一个 <code>GAMMA_OUT</code>，位置不同、用途不同；平时说的“Gamma 校正”通常指输出侧的 <code>GAMMA_OUT</code>。</p><p>（3）<strong>4:2:0 是最后一步才做的</strong>：<code>CSM</code> 先把 RGB 变成 YUV444，<code>CONV422</code> 再降到 YUV422；要输出 4:2:0 还得靠 <code>SELF_RESIZE</code> / <code>SCL</code>（TRM 明确写了 Resize 支持 4:2:2 ↔ 4:2:0 的相互转换）。所以 ISP 默认输出多是 YUV422，YUV420 由 Resize 或后级模块决定。</p><h2 id="四、-总结" tabindex="-1">四、 总结 <a class="header-anchor" href="#四、-总结" aria-label="Permalink to &quot;四、 总结&quot;">​</a></h2><p>把整条链路串起来：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sensor：I2C/CCI 配置 + MCLK 时钟，逐行读出（光电转换 → 模拟增益 → ADC → Bayer RAW，每像素 1 个分量，10bit）</span></span>
<span class="line"><span>   ↓ DVP 并口，或 MIPI CSI-2（差分，经 D-PHY）</span></span>
<span class="line"><span>SoC：D-PHY → CSI2RX 还原成像素，交给 ISP（或经 VICAP 直存 DDR）</span></span>
<span class="line"><span>   ↓ 解包 + 校正（黑电平、镜头阴影、坏点、去噪、白平衡）</span></span>
<span class="line"><span>仍是 Bayer，1 个分量（按 16bit 存放，2 字节/像素）</span></span>
<span class="line"><span>   ↓ 去马赛克（插值补齐）</span></span>
<span class="line"><span>RGB，3 个分量（8bit x 3，3 字节/像素）   ← 数据量变大的一步</span></span>
<span class="line"><span>   ↓ 色彩空间转换</span></span>
<span class="line"><span>YUV444，3 个分量（3 字节/像素）</span></span>
<span class="line"><span>   ↓ 色度下采样（U、V 各 2:1）</span></span>
<span class="line"><span>YUV420，1.5 字节/像素                    ← 数据量变小的一步</span></span>
<span class="line"><span>   ↓ 按 I420 / NV12 排布</span></span>
<span class="line"><span>裸数据文件（无头信息，1920x1080 一帧 2.97MB）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>最后留三个容易搞混的点：</p><ul><li>数据量变大发生在<strong>去马赛克</strong>（1 个分量 → 3 个分量），变小发生在<strong>色度下采样</strong>（3 字节 → 1.5 字节）。</li><li>YUV420 之所以看着不糊，是因为色度下采样只降低了“颜色”的精度，<strong>亮度 Y 一点没降</strong>，而人眼对亮度最敏感。</li><li>相机不一定都给 RAW：带 ISP 的 sensor（很多手机 sensor、USB 摄像头）直接输出 YUV422 / YUV420，此时拿到手的可能就已经是 NV12 / NV21 了，本文前半段那条“RAW → ISP → RGB”的路径在 sensor 内部已经走完了。</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,110)])])}const _=a(c,[["render",b]]);export{P as __pageData,_ as default};
